208: ```motoko filepath=src/backend/mixins/gmail-config.mo
209: import AccessControl "mo:caffeineai-authorization/access-control";
210: import Runtime "mo:core/Runtime";
211: 
212: mixin (
213:   accessControlState : AccessControl.AccessControlState,
214:   gmailConfig : { var clientId : Text; var clientSecret : Text },
215: ) {
216:   public query func isGmailConfigured() : async Bool {
217:     gmailConfig.clientId.size() > 0;
218:   };
219: 
220:   public shared ({ caller }) func setGmailCredentials(clientId : Text, clientSecret : Text) : async () {
221:     if (not AccessControl.hasPermission(accessControlState, caller, #admin)) {
222:       Runtime.trap("Unauthorized: Only admins can set Gmail credentials");
223:     };
