230: ```motoko filepath=src/backend/mixins/gmail-messaging.mo
231: import Map "mo:core/Map";
232: import Principal "mo:core/Principal";
233: import Runtime "mo:core/Runtime";
234: import LibGmail "../lib/gmail";
235: 
236: mixin (
237:   gmailConfig : { var clientId : Text; var clientSecret : Text },
238:   gmailConnections : Map.Map<Principal, LibGmail.GmailConnection>,
239:   pendingGmailFlows : Map.Map<Principal, LibGmail.PendingOAuth>,
240: ) {
241:   public query ({ caller }) func isMyGmailConnected() : async Bool {
242:     Map.containsKey(gmailConnections, Principal.compare, caller);
243:   };
244: 
245:   public query ({ caller }) func getMyGmailEmailAddress() : async ?Text {
246:     if (caller.isAnonymous()) {
247:       Runtime.trap("Sign in to view your connected Gmail address");
248:     };
249:     switch (Map.get(gmailConnections, Principal.compare, caller)) {
250:       case (?connection) ?connection.emailAddress;
251:       case null null;
252:     };
253:   };
254: 
255:   public shared ({ caller }) func startGmailOAuth(redirectUri : Text) : async Text {
256:     if (caller.isAnonymous()) {
257:       Runtime.trap("Sign in to connect Gmail");
258:     };
259:     if (gmailConfig.clientId.size() == 0) {
260:       Runtime.trap("Gmail is not configured (admin must set credentials)");
261:     };
262:     await* LibGmail.startAuthorize(
263:       gmailConfig.clientId, redirectUri, caller, pendingGmailFlows,
264:     );
265:   };
266: 
267:   public shared ({ caller }) func completeGmailOAuth(code : Text, state : Text) : async () {
268:     if (caller.isAnonymous()) {
269:       Runtime.trap("Sign in to connect Gmail");
270:     };
271:     if (gmailConfig.clientId.size() == 0) {
272:       Runtime.trap("Gmail is not configured");
273:     };
274:     let ?pending = Map.get(pendingGmailFlows, Principal.compare, caller) else {
275:       Runtime.trap("No pending OAuth flow — call startGmailOAuth first");
276:     };
277:     if (state != pending.state) {
278:       Runtime.trap("OAuth state did not match the pending Gmail flow");
279:     };
280:     Map.remove(pendingGmailFlows, Principal.compare, caller);
281:     let connection = await* LibGmail.exchangeCode(
282:       gmailConfig.clientId, gmailConfig.clientSecret, code,
283:       pending.redirectUri, pending.codeVerifier,
284:     );
285:     Map.add(gmailConnections, Principal.compare, caller, connection);
286:   };
287: 
288:   public shared ({ caller }) func sendEmail(
289:     to : Text, subject : Text, body : Text,
290:   ) : async Text {
291:     if (caller.isAnonymous()) {
292:       Runtime.trap("Sign in to send email");
293:     };
294:     let ?connection = Map.get(gmailConnections, Principal.compare, caller) else {
295:       Runtime.trap("Connect your Gmail account first");
296:     };
297:     await* LibGmail.sendEmail(
298:       gmailConfig.clientId, gmailConfig.clientSecret, connection, caller,
299:       gmailConnections, to, subject, body,
300:     );
301:   };
302: 
303:   public shared ({ caller }) func disconnectMyGmail() : async () {
304:     if (caller.isAnonymous()) {
305:       Runtime.trap("Sign in to disconnect");
306:     };
307:     Map.remove(gmailConnections, Principal.compare, caller);
308:   };
309: };
310: ```
311: 
312: ```motoko filepath=src/backend/lib/gmail.mo
313: import Map "mo:core/Map";
314: import Nat64 "mo:core/Nat64";
315: import Principal "mo:core/Principal";
316: import Text "mo:core/Text";
317: import Runtime "mo:core/Runtime";
318: import OAuth "mo:google-oauth/OAuth";
319: import { gmail_users_messages_send } "mo:googlemail-client/Apis/UsersApi";
320: import { type Message; JSON = Message } "mo:googlemail-client/Models/Message";
321: import { defaultConfig; type Config } "mo:googlemail-client/Config";
322: 
323: module {
324:   public type GmailConnection = {
325:     accessToken : Text;
326:     refreshToken : Text;
327:     emailAddress : Text;
328:   };
329: 
330:   public type PendingOAuth = {
331:     codeVerifier : Text;
332:     redirectUri : Text;
333:     state : Text;
334:   };
335: 
336:   // Send-only: learn the address via OIDC userinfo (`openid email`), so no
337:   // `gmail.readonly`. Add `.../gmail.readonly` here ONLY if the app reads mail.
338:   let SCOPES : Text = "openid email https://www.googleapis.com/auth/gmail.send";
339: 
340:   func configForToken(token : Text) : Config {
341:     {
342:       defaultConfig with
343:       auth = ?#bearer(token);
344:       is_replicated = ?false;
345:       max_response_bytes = ?Nat64.fromNat(2_000_000);
346:     };
347:   };
348: 
349:   public func startAuthorize(
350:     clientId : Text, redirectUri : Text, caller : Principal,
351:     pendingFlows : Map.Map<Principal, PendingOAuth>,
352:   ) : async* Text {
353:     let codeVerifier = await OAuth.generateCodeVerifier();
354:     let state = await OAuth.generateCodeVerifier();
355:     Map.add(pendingFlows, Principal.compare, caller, {
356:       codeVerifier;
357:       redirectUri;
358:       state;
359:     });
360:     OAuth.buildAuthorizeUrl(clientId, redirectUri, SCOPES, state, OAuth.computeCodeChallenge(codeVerifier));
361:   };
362: 
363:   public func exchangeCode(
364:     clientId : Text, clientSecret : Text, code : Text,
365:     redirectUri : Text, codeVerifier : Text,
366:   ) : async* GmailConnection {
367:     let tokens = await OAuth.exchangeAuthorizationCode(clientId, clientSecret, code, redirectUri, codeVerifier);
368:     let accessToken = accessTokenOf(tokens, "Token exchange");
369:     let refreshToken = tokens.refreshToken
370:       ?? Runtime.trap("Token exchange failed: missing refresh_token");
371:     // Learn the connected address via OIDC userinfo — needs only `openid email`,
372:     // never `gmail.readonly`. (If the app also reads mail and requests
373:     // `gmail.readonly`, `gmail_users_getProfile` is an equivalent alternative.)
374:     let emailAddress = (await OAuth.getUserEmail(accessToken))
375:       ?? Runtime.trap("Failed to fetch connected email from userinfo");
376:     { accessToken; refreshToken; emailAddress };
377:   };
378: 
379:   /// Send an email. On HTTP 401, refreshes the access token once and retries.
380:   /// Persists the refreshed token into `gmailConnections` keyed by `caller`.
381:   public func sendEmail(
382:     clientId : Text, clientSecret : Text, connection : GmailConnection,
383:     caller : Principal, gmailConnections : Map.Map<Principal, GmailConnection>,
384:     to : Text, subject : Text, body : Text,
385:   ) : async* Text {
386:     let rawMessage = "To: " # to # "\r\n"
387:       # "Subject: " # subject # "\r\n"
388:       # "Content-Type: text/plain; charset=UTF-8\r\n\r\n" # body;
389:     let message : Message = { Message.init {} with raw = ?rawMessage.encodeUtf8() };
390:     try {
391:       messageIdOf(await* gmail_users_messages_send(
392:         configForToken(connection.accessToken), "me", #_1_, "", #json, "", "", "", "", true, "", "", "", message,
393:       ));
394:     } catch e {
395:       let msg = e.message();
396:       if (not (msg.contains(#text("401")) or msg.contains(#text("Unauthorized")))) {
397:         Runtime.trap("Gmail send failed: " # msg);
398:       };
399:       let refreshed = await OAuth.refreshAccessToken(clientId, clientSecret, connection.refreshToken);
400:       let newToken = accessTokenOf(refreshed, "Token refresh");
401:       Map.add(gmailConnections, Principal.compare, caller, {
402:         connection with accessToken = newToken;
403:       });
404:       messageIdOf(await* gmail_users_messages_send(
405:         configForToken(newToken), "me", #_1_, "", #json, "", "", "", "", true, "", "", "", message,
406:       ));
407:     };
408:   };
409: 
410:   func accessTokenOf(tokens : OAuth.TokenResponse, operation : Text) : Text {
411:     switch (tokens.error) {
412:       case (?error) {
413:         let description = switch (tokens.errorDescription) {
414:           case (?value) ": " # value;
415:           case null "";
416:         };
417:         Runtime.trap(operation # " failed: " # error # description);
418:       };
419:       case null {};
420:     };
421:     tokens.accessToken ?? Runtime.trap(operation # " failed: missing access_token");
422:   };
423: 
424:   func messageIdOf(result : Message) : Text = result.id ?? "";
425: };
426: ```
427: 
428: ## 5. Available API surface
429: 
430: ### `google-oauth` (OAuth 2.0 mechanics)
431: 
432: | Function | Purpose |
433: | --- | --- |
434: | `OAuth.urlEncode(text)` | RFC 3986 percent-encoding for form bodies |
435: | `OAuth.parseTokenResponse(text)` | Parse Google token-endpoint JSON |
436: | `OAuth.exchangeAuthorizationCode(...)` | Exchange auth code for tokens |
437: | `OAuth.refreshAccessToken(...)` | Refresh an expired access token |
438: | `OAuth.generateCodeVerifier()` | Generate PKCE `code_verifier` (on-chain randomness) |
439: | `OAuth.computeCodeChallenge(verifier)` | Compute PKCE `code_challenge` (S256) |
440: | `OAuth.buildAuthorizeUrl(...)` | Build the Google OAuth authorize URL |
441: | `OAuth.getUserEmail(accessToken)` | Fetch the connected email via OIDC userinfo (needs only `openid email`) |
442: 
443: ### `googlemail-client` (Gmail REST API)
444: 
445: The canonical actor above intentionally implements only profile lookup and
446: message sending. For another generated operation, keep bearer authentication
447: and `is_replicated = ?false`, then apply the same single-refresh-retry pattern
448: as `sendEmail`.
449: 
450: | Function | Purpose |
451: | --- | --- |
452: | `gmail_users_messages_send` | Send an RFC 5322 message |
453: | `gmail_users_messages_get` | Get a message by id |
454: | `gmail_users_messages_list` | List messages in mailbox |
455: | `gmail_users_drafts_create` | Create a draft |
456: | `gmail_users_drafts_send` | Send a draft by id |
457: | `gmail_users_drafts_get` | Get a draft by id |
458: | `gmail_users_drafts_list` | List drafts |
459: | `gmail_users_getProfile` | Get the user's profile (email, totals) |
460: 
461: ## 6. Cycles and response sizes
462: 
463: The `google-oauth` library uses `Call.httpRequest` from `mo:ic/Call`, which
464: auto-computes and attaches the exact required cycles via the
465: `ic0.cost_http_request` system API. No manual cycle budgeting is needed
466: for token exchange or refresh calls.
467: 
468: For `googlemail-client` calls, `defaultConfig.cycles = 30_000_000_000`
469: (30B). A typical send costs ~10–15B cycles. Bump to 60B for large
470: messages. Set `max_response_bytes = ?2_000_000` for message reads that
471: may include large payloads.
472: 
473: ## 7. Things that will bite you
474: 
475: - **`is_replicated = ?false`** — see §3. Non-negotiable.
476: - **Google refresh tokens do NOT rotate.** Unlike X/Twitter, Google does
477:   not issue a new `refresh_token` on each refresh. Keep the original
478:   `refresh_token` and only persist the new `access_token`. The `sendEmail`
479:   function in §4 handles this.
480: - **Access tokens expire in 1 hour.** The `sendEmail` function catches
481:   HTTP 401, silently refreshes via `google-oauth.refreshAccessToken`, and
482:   retries once. If the refresh also fails, surface "re-connect your account".
483: - **Callback URI exact-match.** Every character (trailing slash, query
484:   string, port) must match between the authorize URL and the redirect.
485:   Google returns `redirect_uri_mismatch` otherwise. Use the fixed
486:   `window.location.origin + "/connect/gmail"` for `redirectUri` — the same
